import { breakpoints } from 'app/theme/foundation';
import { DRAWER_HEADER_ROW_HEIGHT } from 'app/theme/components/zimmDrawerShared';

// Figma's actual named drawer sizes (SFCC-898) — five named sizes, not the three/four this
// file previously guessed at. Each name below matches Figma's own naming exactly, so there's
// no re-deriving which number belongs to which concept next time this file is touched:
//
//   Desktop Large — 50%  — Product Details, Filters (desktop width)
//   Tablet        — 80%  — Product Details, Filters (tablet width)
//   Desktop Small — 25%  — Notify Me, Wishlist, Find in Boutique, Regional Storefront,
//                           Cookies, Login
//   X-Large       — 82%  — Cart (not yet built as a drawer — see the `xLarge` variant below)
//   Mobile        — unchanged, the baseStyle treatment every variant collapses to below `md`.
//
// An earlier revision of this file measured 82% off a Figma frame annotated "Tablet = 82% of
// screen" and used it as `small`'s (now `tablet`'s) value — that frame's annotation was wrong
// (or superseded): 82% is actually X-Large's value (Cart), a completely different drawer this
// codebase hasn't built yet, and Tablet is genuinely 80%. Corrected once confirmed directly
// against the list above, not another single frame's own label.
const WIDTH_LARGE = '50%';
const WIDTH_TABLET = '80%';
// The original width set when this drawer shell was first built (2026-08-27) — matches Figma's
// "Desktop Small" exactly. Used by every viewport-independent narrow utility drawer (Find in
// Boutique today; Notify Me/Wishlist/Regional Storefront/Cookies/Login once those exist).
const WIDTH_SMALL = '25%';
// Cart isn't built as a drawer yet (confirmed: it's a full page today) — this constant and the
// `xLarge` variant below exist so the real Figma value is already in place, under the right
// name, whenever that work starts, rather than needing this same "which number is this?"
// investigation again.
const WIDTH_XLARGE = '82%';

// SFCC-831 — Figma-confirmed narrow-panel width floor (402px), the language/country-mismatch
// prompt's own precondition and the fix for a pre-existing defect: `small`'s 25% only reaches
// its designed 402px at a 1608px viewport, so every laptop under that width renders narrower
// than intended. rem, not px, so the floor still scales with browser zoom the way a fixed panel
// width should. No --zimm-scale equivalent exists yet.
const PANEL_MIN_NARROW = '25.125rem'; // 402px — audit-allow: provisional — pending a --zimm-* foundation token

// Shared by every narrow-panel variant (`small`, `prompt`) above `md`, same technique as
// INSET_COMPACT/INSET_LARGE above, so the width/floor/cap triple can't drift between them the
// way three independently-typed literals would. `maxWidth: '100%'` (not WIDTH_SMALL's own 25%)
// because the minWidth floor would otherwise fight a 25% cap below 1608px.
const NARROW_WIDTH_ABOVE_MD = { width: WIDTH_SMALL, minWidth: PANEL_MIN_NARROW, maxWidth: '100%' };

// Mobile deliberately leaves a strip of backdrop visible below the panel (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Re-measured against node
// 40002218:42903 (SFCC-898): overlay 956px tall, panel 898px tall — exactly 58px. No named
// spacing scale step lands on 58px, so this is a provisional raw value pending a foundation
// token, same as the other pending constants in this file.
const MOBILE_BOTTOM_GAP = '3.625rem'; // 58px

// Close-button inset, measured from the pdp/drawer header frames. `tablet`/`small`/`xLarge`/
// `mobile` all share the same measured inset (32px/40px) at every width — only `large` switches
// to the wider 48px/64px inset, at/above the tablet breakpoint. Below that breakpoint `large`'s
// own override doesn't apply either, and the baseStyle inset is used instead, which is also how
// the whole drawer collapses to the mobile treatment on a narrow viewport regardless of `size`.
const INSET_COMPACT = { top: 'var(--zimm-scale-3xl)', right: 'var(--zimm-scale-2xl)' };
const INSET_LARGE = { top: 'var(--zimm-scale-1200)', right: 'var(--zimm-scale-4xl)' };

// Header constants — from Figma drawer/header frame measurements.
// Compact horizontal inset (small/mobile): px=32px. Large desktop: px=64px.
// Small desktop header uses py=24px. Large desktop: container height=120px (row centred).
// Mobile base: container height=80px.
const HEADER_PADDING_COMPACT_X = 'var(--zimm-scale-2xl)'; // 32px
const HEADER_PADDING_LARGE_X = 'var(--zimm-scale-4xl)'; // 64px
const HEADER_PADDING_Y = 'var(--zimm-scale-xl)'; // 24px — small desktop py
// audit-allow: Figma-confirmed container heights with no --zimm-scale equivalents at these values.
const HEADER_HEIGHT_LARGE = '120px';
// SFCC-831/689 — corrected from 72px: live Playwright measurement of the prompt drawer
// (which inherits this baseStyle value, having no header override of its own — see the
// `prompt` variant below) showed 72px at every width, but Figma's mobile header (node
// 40007204:186159) is a fixed 80px row. This constant is baseStyle, shared by every
// ZimmDrawer size below `md` — but only a consumer that actually renders the in-flow
// `header` part (passes `title`, or `labelledBy` + `boxedHeader`) is affected. Checked
// against every real consumer (rework, tester-confirmed): zimmWishlistAuthDrawer
// (Wishlist, Login) passes `title` and is genuinely widened by this fix; Find in Boutique
// and ZimmPdpDrawer's tab drawer pass neither and use the floating `closeButton` part
// instead (unaffected); Cookies/Notify Me don't exist as built consumers yet. A deliberate
// cross-consumer widening approved 2026-09-12 (Wishlist/Login), not a `prompt`-only
// divergence.
const HEADER_HEIGHT_MOBILE = '80px';

export const ZimmDrawer = {
  parts: ['overlay', 'content', 'closeButton', 'header', 'headerTitle', 'headerCloseButton'],
  baseStyle: {
    // Explicit position/inset rather than relying on Chakra's own built-in `Drawer` overlay
    // styling — confirmed via inspection that it doesn't apply (renders `position: static`,
    // zero size) when the `<Drawer>` isn't given Chakra's own `size` prop, which this component
    // deliberately omits (see maxWidth note below). Owning it here avoids depending on that.
    overlay: {
      position: 'fixed',
      inset: 0,
      background: 'var(--zimm-color-opacity-50)',
      zIndex: 'overlay',
    },
    content: {
      // Chakra's own <DrawerContent> baked in a default white background
      // (@chakra-ui/theme's modal.js `baseStyleDialog`: `bg: colors.white`) that this recipe
      // never needed to set itself while that component was still in use — now that
      // ZimmDrawer hand-rolls its own content element (see index.tsx's file-level comment),
      // nothing supplies one unless it's set here. Matches Figma's pdp/drawer panel background
      // (bg-[var(--brand/color/palette/white,white)]) — --zimm-color-bg-07 resolves to the
      // same grey.white value (SFCC-898 — the panel briefly had no background at all).
      background: 'var(--zimm-color-bg-07)',
      width: '100%',
      // Matches `width` at every step below — Chakra's own `Drawer` theme defaults to
      // `size="xs"` (maxW 20rem) when no `size` prop is passed to `<Drawer>` (deliberate: its
      // fixed size scale has no 50%/25% steps), and that default `maxW` otherwise still caps
      // our own `width` override since we never reset it.
      maxWidth: '100%',
      // A `height` reduction, not a `bottom` offset. Stale note corrected (SFCC-831): this
      // comment used to describe a separate `position: relative` DrawerContent sitting inside a
      // `position: fixed` wrapper — that was true before ZimmDrawer hand-rolled its own content
      // element (see index.tsx's file-level comment); today `content`'s styles land directly on
      // the SAME `position: fixed; top: 0; right: 0; bottom: 0` element (index.tsx's
      // `MotionChakraDiv`). `bottom` is therefore live on this element, not inert — a percentage
      // `height` here still resolves correctly against `top`+`bottom` (no gap-not-rendering
      // regression, SFCC-898's original concern), but `height: 'auto'` behaves differently: with
      // both `top` and `bottom` pinned, `auto` stretches to fill rather than shrinking to
      // content. See the `prompt` variant below (SFCC-831) for the one size that hit this and
      // its `bottom: 'auto'` fix.
      height: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
      // Header stays fixed; only the content area (ZimmPdpDrawer's own `content` part) scrolls —
      // AC 10, "content area scrolls independently without the tab header scrolling".
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    // Was missing `position: absolute` since this component's original commit — the
    // top/right insets below were silently no-ops (closeButton rendered as a normal in-flow
    // block instead of overlaying the header's corner), which is the root cause of SFCC-898's
    // close-button-misaligned-with-tabs defect across every breakpoint.
    //
    // height/display/alignItems/justifyContent: matches zimmTabs.css.ts's `menu.minHeight`
    // (DRAWER_HEADER_ROW_HEIGHT, zimmDrawerShared.ts) and centers the icon inside it — the
    // close icon's own intrinsic size doesn't equal the tab row's real rendered height, so
    // matching only `top` between the two (as before) left their vertical centers slightly
    // offset (SFCC-898, mobile). Only applies to the floating close button (no `title` passed) —
    // the inline title-row close button below is a normal flex child, not absolutely positioned.
    closeButton: {
      position: 'absolute',
      ...INSET_COMPACT,
      height: DRAWER_HEADER_ROW_HEIGHT,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    // Drawer header — title (flex-1, left) + close button (right).
    // baseStyle applies the mobile/compact treatment: px=32px, container h=80px centred.
    header: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xs)',
      backgroundColor: 'var(--zimm-color-text-inverse)',
      paddingInline: HEADER_PADDING_COMPACT_X,
      paddingBlock: 0,
      minHeight: HEADER_HEIGHT_MOBILE,
      flexShrink: 0,
    },
    headerTitle: {
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      whiteSpace: 'nowrap',
    },
    // SFCC-831/689 rework — gives the close button its own real 44px row inside the in-flow
    // header (index.tsx's `title`/`boxedHeader` branch), matching Figma's
    // `drawer-header-options` row exactly. The floating case (no title/boxedHeader) already
    // gets this via `closeButton`'s own `height: DRAWER_HEADER_ROW_HEIGHT` above — this is the
    // same treatment for the boxed case, which previously had no wrapper at all and fell back
    // to the button's own (smaller) intrinsic size — root cause of this rework's defect.
    // Does NOT change rendered output for any `minHeight`-driven header (large/xLarge/small/
    // mobile) — nested `alignItems: 'center'` centring resolves to the identical visual
    // midpoint either way. It only matters for `paddingBlock`-driven sizing (`xLarge`,
    // `prompt`), where no `minHeight` exists to force the header's total height, so the row's
    // own real height is what the padding is measured against.
    headerCloseButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      height: DRAWER_HEADER_ROW_HEIGHT,
      flexShrink: 0,
    },
  },
  variants: {
    large: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_LARGE,
          maxWidth: WIDTH_LARGE,
          height: '100%',
        },
      },
      closeButton: {
        [`@media (min-width: ${breakpoints.md})`]: INSET_LARGE,
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          paddingInline: HEADER_PADDING_LARGE_X,
          minHeight: HEADER_HEIGHT_LARGE,
        },
      },
    },
    // Figma's "Tablet" size — the tablet-range step for Product Details/Filters, which
    // graduates to `large` (Desktop Large) at the desktop breakpoint via the caller's own
    // useBreakpointValue (ZimmPdpDrawer never selects this variant itself).
    tablet: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_TABLET,
          maxWidth: WIDTH_TABLET,
          height: '100%',
        },
      },
    },
    // Figma's "Desktop Small" — always narrow, at every width above the mobile collapse. No
    // js-level graduation to another variant the way `tablet` graduates to `large` — this is
    // the whole point for its utility-drawer consumers (Find in Boutique today).
    small: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          ...NARROW_WIDTH_ABOVE_MD,
          height: '100%',
        },
      },
      // SFCC-831/689 (A6) — `small` had no `header` override at all either, the same defect
      // class `prompt` had before A5 (see that variant's own comment above): it silently
      // inherited baseStyle.header's mobile/compact treatment (paddingBlock: 0, minHeight:
      // HEADER_HEIGHT_MOBILE) at every breakpoint, including desktop/tablet. Live Playwright
      // measurement of commerce-zimmwishlistauthdrawer--default — zimmWishlistAuthDrawer, the
      // real, only consumer that renders `small`'s `header` part (it passes `title`) — showed
      // 80px at 390px, 834px, AND 1440px: identical everywhere. Figma's pdp/drawer component
      // (the shared template both `small`'s and `prompt`'s consumers instantiate) returned
      // byte-identical header chrome across 4 independent fetches this session regardless of
      // which content variant instantiates it (Location at Desktop Small/Tablet/Mobile,
      // Language at Desktop Small): py-24px wrapping a 44px row = 92px total at md+, 80px
      // fixed on mobile — the same spec `prompt.header`'s own comment above already cites.
      // `small`'s own variant comment directly above already names this variant "Desktop
      // Small" itself, and `prompt.header`'s comment cites that same category for its header
      // spec — both point at one shared Figma component, not two independently-designed
      // headers. No Wishlist/Login-specific Figma frame was available to cite directly this
      // session; approved 2026-09-13 to fix from this shared-component evidence rather than
      // wait for one. Same shape as `prompt`'s and `xLarge`'s own header overrides.
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y,
        },
      },
    },
    // SFCC-831 — the country/language mismatch prompt. Below `md` it sizes to its own content
    // (a short banner, not a viewport-relative panel) capped by the same MOBILE_BOTTOM_GAP the
    // baseStyle content height already reserves, and scrolls internally if content overflows
    // that cap. Above `md` it becomes a normal narrow utility drawer — same width/floor as
    // `small` — with a full-height panel, matching every other size variant's shape there.
    prompt: {
      content: {
        height: 'auto',
        // index.tsx's `__css` (`ZimmDrawerContent`'s `MotionChakraDiv`) sets
        // `position: 'fixed', top: 0, right: 0, bottom: 0` on the sliding panel itself, then
        // spreads this `content` part on top — so `bottom: 0` is still live here unless a part
        // value overrides it. For a fixed box with BOTH `top` and `bottom` pinned to definite
        // values, `height: 'auto'` does NOT mean "shrink to content": the browser instead solves
        // `top + height + bottom = containing-block height`, i.e. it STRETCHES to fill the gap —
        // exactly reproducing every other size's viewport-minus-gap height. `bottom: 'auto'`
        // removes that second definite constraint so `top: 0` alone anchors the panel and
        // `height: 'auto'` can finally resolve via real shrink-to-fit rules against this part's
        // own `display: flex; flexDirection: column` (baseStyle.content) — i.e. the sum of its
        // children's heights. Deleting this line silently reintroduces the bug it fixes: a
        // recipe-value test asserting `height === 'auto'` cannot detect the regression, because
        // that string doesn't change — only a real rendered/computed-height check can.
        bottom: 'auto',
        maxHeight: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
        overflowY: 'auto',
        [`@media (min-width: ${breakpoints.md})`]: {
          ...NARROW_WIDTH_ABOVE_MD,
          height: '100%',
          // Explicit reset, matching every other size's own explicit values at this breakpoint
          // rather than silently inheriting the base level's `bottom: 'auto'` above. `height` is
          // already an explicit '100%' here (same as every other size), so the shrink-vs-stretch
          // distinction the base level cares about doesn't apply above `md` either way — this is
          // purely so a future reader isn't left wondering why `bottom` isn't `0` like every
          // other variant at this breakpoint.
          bottom: 0,
          maxHeight: '100%',
        },
      },
      // SFCC-831/689 — `prompt` had no `header` override at all, so it silently inherited
      // baseStyle.header's mobile/compact treatment (paddingBlock: 0, minHeight:
      // HEADER_HEIGHT_MOBILE) at every breakpoint, including desktop/tablet where Figma wants
      // the taller auto-height treatment instead. Figma's Desktop Small (node 40002218:52408)
      // and Tablet (node 40007204:186134) both return the identical header spec — py-24px
      // wrapping a 44px close-icon row, auto-height to 92px total — at both breakpoints, i.e.
      // one `md+` step, not two separate tablet/desktop values. Same shape as `xLarge`'s own
      // header override below.
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y, // already defined, currently only consumed by xLarge — 24px
        },
      },
    },
    // Figma's "X-Large" (Cart) — not consumed anywhere yet (Cart is a full page today, not a
    // drawer), but the real value is already here under the right name for when that changes.
    xLarge: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_XLARGE,
          maxWidth: WIDTH_XLARGE,
          height: '100%',
        },
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y,
        },
      },
    },
    // No override — the baseStyle above already is the mobile treatment.
    mobile: {},
  },
};

content.content:
1	import { describe, test, expect } from 'vitest';
2	import { breakpoints } from 'app/theme/foundation';
3	import { ZimmDrawer } from './zimmDrawer.css';
4	
5	/**
6	 * Recipe-value tests for SFCC-831's narrow-panel width floor (`small`, `prompt`) and the new
7	 * `prompt` size itself. `ZimmDrawer`'s `variants` are plain style objects, not a function of
8	 * props (unlike zimmSizeChip.css.ts / zimmTextInput.css.ts), so these assertions read the
9	 * resolved object directly instead of calling a resolver — same reasoning as those two files'
10	 * own docblocks: a `.css.test.ts` reading a plain object is trivially capable of passing against
11	 * a recipe that was never changed, which is exactly why each assertion below was proven red
12	 * against the pre-change recipe first (see the step's fail-on-purpose sub-step), then reverted.
13	 */
14	
15	const MD_QUERY = `@media (min-width: ${breakpoints.md})`;
16	
17	/**
18	 * `prompt.content`'s inferred type unions every property VALUE in the object — the plain
19	 * strings from its own base-level `height`/`maxHeight`/`overflowY` alongside the computed
20	 * `@media` key's own object value — because TypeScript synthesises one index-signature value
21	 * type across an object literal that mixes named string props with a single non-literal
22	 * computed key (`small.content`, which has no named props at that level, doesn't hit this; see
23	 * footer.css.ts's `subscribe` part for the identical mixed shape in production code, unaffected
24	 * only because it isn't read back here through a type-checked index). Narrows with a real type
25	 * guard rather than an `as` cast, per typescript.md's preference for `unknown` + a guard over an
26	 * assertion.
27	 */
28	const isMediaQueryStyles = (value: unknown): value is Record<string, string> =>
29	  typeof value === 'object' && value !== null;
30	
31	const stylesAboveMd = (content: Record<string, unknown>): Record<string, string> => {
32	  const value = content[MD_QUERY];
33	  if (!isMediaQueryStyles(value)) {
34	    throw new Error(`expected "${MD_QUERY}" to resolve to a style object, got ${typeof value}`);
35	  }
36	  return value;
37	};
38	
39	describe('ZimmDrawer — narrow-panel width floor (small, prompt share one 402px floor)', () => {
40	  test('small emits the 402px minWidth floor above md', () => {
41	    expect(stylesAboveMd(ZimmDrawer.variants.small.content).minWidth).toBe('25.125rem');
42	  });
43	
44	  test('prompt emits the same 402px minWidth floor above md', () => {
45	    expect(stylesAboveMd(ZimmDrawer.variants.prompt.content).minWidth).toBe('25.125rem');
46	  });
47	
48	  test('small no longer caps at the old 25% maxWidth (width itself, WIDTH_SMALL, is untouched)', () => {
49	    const aboveMd = stylesAboveMd(ZimmDrawer.variants.small.content);
50	    expect(aboveMd.width).toBe('25%');
51	    expect(aboveMd.maxWidth).not.toBe('25%');
52	    expect(aboveMd.maxWidth).toBe('100%');
53	  });
54	});
55	
56	describe('ZimmDrawer — prompt size (sizes to its own content below md, full-height panel above)', () => {
57	  test('base level: auto height, capped by the mobile-bottom-gap calc(), scrolls internally', () => {
58	    const base = ZimmDrawer.variants.prompt.content;
59	    expect(base.height).toBe('auto');
60	    expect(base.maxHeight).toBe('calc(100% - 3.625rem)');
61	    expect(base.overflowY).toBe('auto');
62	  });
63	
64	  // `bottom: 'auto'` is the actual fix (SFCC-831): the sliding panel is `position: fixed`
65	  // with `top`/`bottom` both pinned by index.tsx's own `__css` (see zimmDrawer.css.ts's inline
66	  // comment on this line), so `height: 'auto'` alone stretches to fill rather than shrinking to
67	  // content. This assertion only proves the string is present in the recipe object — it was
68	  // deliberately NOT trusted as sufficient proof on its own; the real proof is the live
69	  // Playwright measurement (before/after/reverted) recorded in this step's report, since a
70	  // jsdom-level object read cannot observe CSS positioning/sizing behaviour at all.
71	  test('base level: bottom is auto, not the inherited fixed-panel 0 (this is what makes height: auto shrink-to-content instead of stretch-to-fill)', () => {
72	    const base = ZimmDrawer.variants.prompt.content;
73	    expect(base.bottom).toBe('auto');
74	  });
75	
76	  test('above md: full height, maxHeight resets to 100% (no calc() cap)', () => {
77	    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.content);
78	    expect(aboveMd.height).toBe('100%');
79	    expect(aboveMd.maxHeight).toBe('100%');
80	  });
81	
82	  test('above md: bottom is explicitly reset to 0, matching every other size at this breakpoint', () => {
83	    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.content);
84	    expect(aboveMd.bottom).toBe(0);
85	  });
86	});
87	
88	describe('ZimmDrawer — parts array', () => {
89	  // SFCC-831/689 rework: gains exactly one new part, `headerCloseButton` (the boxed close
90	  // button's own 44px row — see zimmDrawer.css.ts), fixing the tester-caught defect where
