import { describe, test, expect } from 'vitest';
import { breakpoints } from 'app/theme/foundation';
import { ZimmDrawer } from './zimmDrawer.css';

/**
 * Recipe-value tests for SFCC-831's narrow-panel width floor (`small`, `prompt`) and the new
 * `prompt` size itself. `ZimmDrawer`'s `variants` are plain style objects, not a function of
 * props (unlike zimmSizeChip.css.ts / zimmTextInput.css.ts), so these assertions read the
 * resolved object directly instead of calling a resolver — same reasoning as those two files'
 * own docblocks: a `.css.test.ts` reading a plain object is trivially capable of passing against
 * a recipe that was never changed, which is exactly why each assertion below was proven red
 * against the pre-change recipe first (see the step's fail-on-purpose sub-step), then reverted.
 */

const MD_QUERY = `@media (min-width: ${breakpoints.md})`;

/**
 * `prompt.content`'s inferred type unions every property VALUE in the object — the plain
 * strings from its own base-level `height`/`maxHeight`/`overflowY` alongside the computed
 * `@media` key's own object value — because TypeScript synthesises one index-signature value
 * type across an object literal that mixes named string props with a single non-literal
 * computed key (`small.content`, which has no named props at that level, doesn't hit this; see
 * footer.css.ts's `subscribe` part for the identical mixed shape in production code, unaffected
 * only because it isn't read back here through a type-checked index). Narrows with a real type
 * guard rather than an `as` cast, per typescript.md's preference for `unknown` + a guard over an
 * assertion.
 */
const isMediaQueryStyles = (value: unknown): value is Record<string, string> =>
  typeof value === 'object' && value !== null;

const stylesAboveMd = (content: Record<string, unknown>): Record<string, string> => {
  const value = content[MD_QUERY];
  if (!isMediaQueryStyles(value)) {
    throw new Error(`expected "${MD_QUERY}" to resolve to a style object, got ${typeof value}`);
  }
  return value;
};

describe('ZimmDrawer — narrow-panel width floor (small, prompt share one 402px floor)', () => {
  test('small emits the 402px minWidth floor above md', () => {
    expect(stylesAboveMd(ZimmDrawer.variants.small.content).minWidth).toBe('25.125rem');
  });

  test('prompt emits the same 402px minWidth floor above md', () => {
    expect(stylesAboveMd(ZimmDrawer.variants.prompt.content).minWidth).toBe('25.125rem');
  });

  test('small no longer caps at the old 25% maxWidth (width itself, WIDTH_SMALL, is untouched)', () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.small.content);
    expect(aboveMd.width).toBe('25%');
    expect(aboveMd.maxWidth).not.toBe('25%');
    expect(aboveMd.maxWidth).toBe('100%');
  });
});

describe('ZimmDrawer — prompt size (sizes to its own content below md, full-height panel above)', () => {
  test('base level: auto height, capped by the mobile-bottom-gap calc(), scrolls internally', () => {
    const base = ZimmDrawer.variants.prompt.content;
    expect(base.height).toBe('auto');
    expect(base.maxHeight).toBe('calc(100% - 3.625rem)');
    expect(base.overflowY).toBe('auto');
  });

  // `bottom: 'auto'` is the actual fix (SFCC-831): the sliding panel is `position: fixed`
  // with `top`/`bottom` both pinned by index.tsx's own `__css` (see zimmDrawer.css.ts's inline
  // comment on this line), so `height: 'auto'` alone stretches to fill rather than shrinking to
  // content. This assertion only proves the string is present in the recipe object — it was
  // deliberately NOT trusted as sufficient proof on its own; the real proof is the live
  // Playwright measurement (before/after/reverted) recorded in this step's report, since a
  // jsdom-level object read cannot observe CSS positioning/sizing behaviour at all.
  test('base level: bottom is auto, not the inherited fixed-panel 0 (this is what makes height: auto shrink-to-content instead of stretch-to-fill)', () => {
    const base = ZimmDrawer.variants.prompt.content;
    expect(base.bottom).toBe('auto');
  });

  test('above md: full height, maxHeight resets to 100% (no calc() cap)', () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.content);
    expect(aboveMd.height).toBe('100%');
    expect(aboveMd.maxHeight).toBe('100%');
  });

  test('above md: bottom is explicitly reset to 0, matching every other size at this breakpoint', () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.content);
    expect(aboveMd.bottom).toBe(0);
  });
});

describe('ZimmDrawer — parts array', () => {
  // SFCC-831/689 rework: gains exactly one new part, `headerCloseButton` (the boxed close
  // button's own 44px row — see zimmDrawer.css.ts), fixing the tester-caught defect where
  // `prompt.header`'s paddingBlock-driven height had no real row height to measure against.
  test('gains headerCloseButton, the one new part introduced by this rework', () => {
    expect(ZimmDrawer.parts).toEqual([
      'overlay',
      'content',
      'closeButton',
      'header',
      'headerTitle',
      'headerCloseButton',
    ]);
  });
});

// Completeness gap flagged by the Scorer: the parts-array test above only proves the part's
// NAME exists, not its style values, and `prompt.header`'s own new md+ values had no coverage
// at all — unlike `prompt.content`'s bottom/height/maxHeight above, which already had exactly
// this kind of value assertion. Both assertions below were proven red against the pre-rework
// shape first (headerCloseButton commented out of baseStyle; prompt.header's key removed
// entirely), then reverted, per this file's own established method.
describe('ZimmDrawer — headerCloseButton (SFCC-831/689 rework)', () => {
  test('gives the boxed close button a real 44px in-flow row', () => {
    expect(ZimmDrawer.baseStyle.headerCloseButton.height).toBe('2.75rem'); // DRAWER_HEADER_ROW_HEIGHT
  });

  test("prompt's header switches to auto-height/24px padding above md", () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.header);
    expect(aboveMd.minHeight).toBe('unset');
    expect(aboveMd.paddingBlock).toBe('var(--zimm-scale-xl)'); // HEADER_PADDING_Y
  });
});

// SFCC-831/689 follow-up (A6): `small` had no `header` override at all — the same defect
// class as `prompt` above, tester-caught via live Playwright measurement of
// commerce-zimmwishlistauthdrawer--default (zimmWishlistAuthDrawer, the only built consumer
// that renders `small`'s `header` part): 80px at 390px, 834px, AND 1440px, identical
// everywhere. Proven red against the pre-fix shape first (`small.header` was `undefined`,
// so `stylesAboveMd` threw reading the media-query key off it), then reverted, per this
// file's own established method (see the headerCloseButton/prompt.header pair above).
describe('ZimmDrawer — small size header (SFCC-831/689 rework)', () => {
  test("small's header switches to auto-height/24px padding above md, matching prompt and xLarge", () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.small.header);
    expect(aboveMd.minHeight).toBe('unset');
    expect(aboveMd.paddingBlock).toBe('var(--zimm-scale-xl)'); // HEADER_PADDING_Y
  });
});

