import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import { IconButton } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { ZimmWishlistAuthDrawer } from './index';

// ZimmWishlistAuthDrawer calls useWishlistAuthDrawer which uses useCurrentCustomer →
// useCustomerType → shopperCustomers SDK client. The global preview.tsx Commerce provider
// does not initialise shopperCustomers, so a story-level provider is required — same
// pattern as rightBar/index.stories.tsx and its CommerceProviders wrapper.
const storybookQueryClient = new QueryClient({
  defaultOptions: { queries: { retry: false, refetchOnWindowFocus: false } },
});

const CommerceProviders = ({ children }: { children: React.ReactNode }) => (
  <QueryClientProvider client={storybookQueryClient}>
    <CommerceApiProvider
      clientId="00000000-0000-0000-0000-000000000000"
      organizationId="f_ecom_storybook_001"
      shortCode="storybook"
      siteId="ZimmermannAU"
      locale="en-AU"
      currency="AUD"
      proxy="https://storybook.invalid/mobify/proxy/api"
      redirectURI="https://storybook.invalid/callback"
      disableAuthInit
      silenceWarnings
    >
      {children}
    </CommerceApiProvider>
  </QueryClientProvider>
);

const meta: Meta<typeof ZimmWishlistAuthDrawer> = {
  title: 'Commerce/ZimmWishlistAuthDrawer',
  component: ZimmWishlistAuthDrawer,
  // This organism calls SFCC SDK hooks (useCurrentCustomer, useAuthHelper) and reads
  // getConfig() for the login feature flags — it requires CommerceApiProvider and
  // pwa-kit-runtime SSR config to be present in the Storybook preview environment.
  // Auth-gate logic and trigger-capture behaviour are covered by index.test.tsx.
  parameters: {
    layout: 'padded',
  },
  decorators: [
    (Story) => {
      // getConfig() reads window.__STORE__ in a browser context. Without it useWishlistAuthDrawer
      // throws "Cannot destructure property 'res' of useServerContext(...)".
      if (typeof window !== 'undefined' && !(window as Window & { __STORE__?: unknown }).__STORE__) {
        (window as Window & { __STORE__?: unknown }).__STORE__ = {
          app: {
            login: {
              passwordless: { enabled: true, mode: 'callback' },
              social: { enabled: true, idps: ['apple', 'google'], redirectURI: '/callback' },
            },
          },
        };
      }
      return (
        <MemoryRouter>
          <MultiSiteProvider
            site={{ id: 'ZimmermannAU', alias: 'au' }}
            locale={{ id: 'en-AU', alias: 'en-AU' }}
            buildUrl={(path: string) => path}
          >
            <CommerceProviders>
              <Story />
            </CommerceProviders>
          </MultiSiteProvider>
        </MemoryRouter>
      );
    },
  ],
};

export default meta;
type Story = StoryObj<typeof ZimmWishlistAuthDrawer>;

/**
 * Click the wishlist icon to open the auth drawer. When the user is not logged in the drawer
 * slides in; when already registered the onAuthSuccess callback fires directly.
 */
export const Default: Story = {
  args: {
    intentId: 'storybook-wishlist',
    onAuthSuccess: () => {},
  },
  render: (args) => (
    <ZimmWishlistAuthDrawer {...args}>
      <IconButton
        aria-label="Wishlist"
        icon={<ZimmIcon type="wishlist" size="lg" aria-hidden={true} />}
        variant="unstyled"
      />
    </ZimmWishlistAuthDrawer>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole('button', { name: /wishlist/i }));
    // ZimmDrawer renders via a Chakra Portal appended to document.body — query there per
    // testing.md's portal exception for within(document.body).
    const body = within(document.body);
    await expect(body.getByRole('dialog')).toBeInTheDocument();
  },
};

