const { chromium } = require('playwright');

const STORY_URL =
  'http://localhost:6006/iframe.html?id=commerce-zimmwishlistauthdrawer--default&viewMode=story';

const VIEWPORTS = [
  { width: 390, height: 844, label: '390px' },
  { width: 834, height: 1194, label: '834px' },
  { width: 1440, height: 900, label: '1440px' },
];

(async () => {
  const browser = await chromium.launch({ headless: true });

  for (const vp of VIEWPORTS) {
    const page = await browser.newPage();
    await page.setViewportSize({ width: vp.width, height: vp.height });
    await page.goto(STORY_URL, { waitUntil: 'networkidle' });

    // The drawer may need a trigger click to open. Look for a role=dialog first;
    // if absent, click whatever trigger renders (a button, typically).
    let dialog = page.getByRole('dialog');
    let dialogVisible = await dialog.isVisible().catch(() => false);

    if (!dialogVisible) {
      const trigger = page.locator('button, [role="button"]').first();
      if (await trigger.count()) {
        await trigger.click();
        await page.waitForTimeout(500);
      }
      dialog = page.getByRole('dialog');
      dialogVisible = await dialog.isVisible().catch(() => false);
    }

    if (!dialogVisible) {
      console.log(`[${vp.label}] ERROR: dialog never became visible`);
      await page.screenshot({ path: `/tmp/zimmdrawer-${vp.width}-noDialog.png`, fullPage: true });
      await page.close();
      continue;
    }

    // Wait for open animation/transition to settle.
    await page.waitForTimeout(600);

    // Find the header: within the dialog, the row containing the title text
    // and the close button. Try common structural approaches.
    const result = await page.evaluate(() => {
      const dialogEl = document.querySelector('[role="dialog"]');
      if (!dialogEl) return { error: 'no dialog element in DOM' };

      // Heuristic 1: element containing both a heading/text node and a button,
      // as a direct child near the top of the dialog.
      const candidates = Array.from(dialogEl.querySelectorAll('*')).filter((el) => {
        const hasButton = el.querySelector('button');
        // header row shouldn't contain the whole dialog content -- keep it shallow
        return hasButton && el.children.length >= 1 && el.children.length <= 6;
      });

      // Prefer the shallowest (closest to dialogEl) matching candidate.
      let best = null;
      let bestDepth = Infinity;
      for (const el of candidates) {
        let depth = 0;
        let cur = el;
        while (cur && cur !== dialogEl) {
          depth++;
          cur = cur.parentElement;
        }
        if (depth < bestDepth) {
          bestDepth = depth;
          best = el;
        }
      }

      if (!best) return { error: 'no header-like element found' };

      const rect = best.getBoundingClientRect();
      const cs = getComputedStyle(best);
      return {
        tagName: best.tagName,
        className: best.className,
        height: rect.height,
        paddingTop: cs.paddingTop,
        paddingBottom: cs.paddingBottom,
        paddingBlockTotal:
          parseFloat(cs.paddingTop || '0') + parseFloat(cs.paddingBottom || '0'),
        minHeight: cs.minHeight,
        outerHTML: best.outerHTML.slice(0, 400),
      };
    });

    console.log(`\n=== Viewport ${vp.label} (${vp.width}x${vp.height}) ===`);
    console.log(JSON.stringify(result, null, 2));

    await page.screenshot({ path: `/tmp/zimmdrawer-${vp.width}.png`, fullPage: false });
    await page.close();
  }

  await browser.close();
})();

